"""flash_attn — iOS shim on torch SDPA.

Real flash-attn is CUDA/Triton-only and can never run on iOS. But its
*algorithmic contract* — memory-efficient exact attention — is provided by
`torch.nn.functional.scaled_dot_product_attention`, which CodeBench routes
to the GPU via the Metal bridge. This shim implements the flash-attn public
API on SDPA so code that hard-imports `flash_attn` runs unchanged (and gets
GPU attention, not an ImportError).

Semantics matched to flash-attn >= 2.1:
  * tensor layout (batch, seqlen, nheads, headdim)
  * GQA/MQA: kv may have fewer heads than q (repeated internally)
  * causal masks align BOTTOM-RIGHT when seqlen_q != seqlen_k (so a
    1-token decode step attends to the whole KV cache) — SDPA's
    `is_causal` is top-left, hence the explicit mask below.

Not implemented (CUDA-specific, no iOS meaning): `window_size` sliding
attention, `alibi_slopes`, `return_attn_probs=True`.
"""
__version__ = "2.5.8"

import torch
import torch.nn.functional as F

__all__ = ["flash_attn_func", "flash_attn_varlen_func", "__version__"]


def _bottom_right_causal_mask(sq, sk, device):
    # position i of q (i in [0,sq)) may attend to j <= i + (sk - sq)
    i = torch.arange(sq, device=device).unsqueeze(1)
    j = torch.arange(sk, device=device).unsqueeze(0)
    return j <= i + (sk - sq)          # bool (sq, sk), True = keep


def _sdpa_bhsd(q, k, v, dropout_p, softmax_scale, causal):
    """q,k,v in (B, H, S, D). Returns (B, H, Sq, D)."""
    if k.shape[1] != q.shape[1]:       # GQA / MQA — repeat kv heads
        rep = q.shape[1] // k.shape[1]
        k = k.repeat_interleave(rep, dim=1)
        v = v.repeat_interleave(rep, dim=1)
    sq, sk = q.shape[2], k.shape[2]
    kwargs = {"dropout_p": dropout_p}
    if softmax_scale is not None:
        kwargs["scale"] = softmax_scale
    if causal and sq == sk:
        return F.scaled_dot_product_attention(q, k, v, is_causal=True, **kwargs)
    if causal:
        mask = _bottom_right_causal_mask(sq, sk, q.device)
        return F.scaled_dot_product_attention(q, k, v, attn_mask=mask, **kwargs)
    return F.scaled_dot_product_attention(q, k, v, **kwargs)


def flash_attn_func(q, k, v, dropout_p=0.0, softmax_scale=None, causal=False,
                    window_size=(-1, -1), alibi_slopes=None,
                    deterministic=False, return_attn_probs=False):
    """q,k,v: (batch, seqlen, nheads, headdim). Returns same layout."""
    if return_attn_probs:
        raise NotImplementedError(
            "flash_attn iOS shim: return_attn_probs is not supported "
            "(use attn_implementation='eager' if you need attention weights)")
    out = _sdpa_bhsd(q.transpose(1, 2), k.transpose(1, 2), v.transpose(1, 2),
                     dropout_p, softmax_scale, causal)
    return out.transpose(1, 2)


def flash_attn_varlen_func(q, k, v, cu_seqlens_q, cu_seqlens_k,
                           max_seqlen_q, max_seqlen_k, dropout_p=0.0,
                           softmax_scale=None, causal=False,
                           window_size=(-1, -1), alibi_slopes=None,
                           deterministic=False, return_attn_probs=False):
    """Variable-length (unpadded) attention.

    q: (total_q_tokens, nheads, headdim); k,v: (total_k_tokens, kv_heads,
    headdim); cu_seqlens_*: (batch+1,) int32 cumulative boundaries.
    Runs SDPA per sequence — batch sizes on iPad are small, so the Python
    loop is negligible next to the attention math itself.
    """
    if return_attn_probs:
        raise NotImplementedError(
            "flash_attn iOS shim: return_attn_probs is not supported")
    out = torch.empty_like(q)
    n = cu_seqlens_q.numel() - 1
    for b in range(n):
        qs, qe = int(cu_seqlens_q[b]), int(cu_seqlens_q[b + 1])
        ks, ke = int(cu_seqlens_k[b]), int(cu_seqlens_k[b + 1])
        if qe == qs:
            continue
        # (S,H,D) -> (1,H,S,D)
        qb = q[qs:qe].transpose(0, 1).unsqueeze(0)
        kb = k[ks:ke].transpose(0, 1).unsqueeze(0)
        vb = v[ks:ke].transpose(0, 1).unsqueeze(0)
        ob = _sdpa_bhsd(qb, kb, vb, dropout_p, softmax_scale, causal)
        out[qs:qe] = ob.squeeze(0).transpose(0, 1)
    return out


def __getattr__(name):
    raise AttributeError(
        f"flash_attn iOS shim: '{name}' is not implemented — only "
        "flash_attn_func / flash_attn_varlen_func / bert_padding are. "
        "The real flash-attn is CUDA-only; on iPad attention runs through "
        "torch SDPA (GPU via the Metal bridge).")
